package com.alpharip.staffmod.cases.detectioncaseautolinker; import java.util.*; public final class DetectionRecord {private final String id,label;private final Map<String,String> attributes;public DetectionRecord(String id,String label,Map<String,String> a){if(id==null||id.trim().isEmpty()||label==null||label.trim().isEmpty())throw new IllegalArgumentException("ID and label required");this.id=id.trim();this.label=label.trim();Map<String,String> c=new LinkedHashMap<String,String>();if(a!=null)for(Map.Entry<String,String> e:a.entrySet())if(e.getKey()!=null&&!e.getKey().trim().isEmpty()&&e.getValue()!=null&&!e.getValue().trim().isEmpty())c.put(e.getKey().trim(),e.getValue().trim());attributes=Collections.unmodifiableMap(c);}public String getId(){return id;}public String getLabel(){return label;}public Map<String,String> getAttributes(){return attributes;}}